import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { Claim } from './claims.service';

export type Grade = 'A' | 'B' | 'C';

export const GRADES: readonly Grade[] = ['A', 'B', 'C'];

export interface Person {
  id: number;
  name: string;
  grade: Grade;
  /** Raised each time the person is saved. */
  version: number;
  /** Retired as soon as a retirement date is set, whatever the date. */
  retired: boolean;
  /** The date the person is retired from (YYYY-MM-DD); null while they are not retired. */
  retiredFrom: string | null;
  /** On hold: their OPEN claims count in no live total while held. */
  held: boolean;
}

/** A patron a person has named: another person on the same sheet. */
export interface Patron {
  id: number;
  personId: number;
  patronId: number;
}

/** What a quick-add made: the person the claim is for (added just now when the name was new) and
 *  the DRAFT claim. */
export interface QuickAdded {
  person: Person;
  claim: Claim;
}

export interface PersonFields {
  name: string;
  grade: Grade;
}

// The people kept on a sheet, read from and written to the server.
@Injectable({ providedIn: 'root' })
export class PeopleService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheet: string): Promise<Person[]> {
    return firstValueFrom(
      this.http.get<Person[]>(this.url(sheet), { headers: this.session.headers() }),
    );
  }

  add(sheet: string, fields: PersonFields): Promise<Person> {
    return firstValueFrom(
      this.http.post<Person>(this.url(sheet), fields, { headers: this.session.headers() }),
    );
  }

  /** Save the person as edited from `version`; refused with 409 and the person as now stored
   *  (`current`) when someone else has saved them since. */
  update(sheet: string, id: number, version: number, fields: PersonFields): Promise<Person> {
    return firstValueFrom(
      this.http.put<Person>(`${this.url(sheet)}/${id}`, { ...fields, version }, {
        headers: this.session.headers(),
      }),
    );
  }

  /** Retire the person from `from` (the sheet's today when null). */
  retire(sheet: string, id: number, from: string | null): Promise<Person> {
    return firstValueFrom(
      this.http.post<Person>(`${this.url(sheet)}/${id}/retire`, { from }, {
        headers: this.session.headers(),
      }),
    );
  }

  /** Put the person on hold (`held` true) or take them off it; refused (409) when they already are. */
  hold(sheet: string, id: number, held: boolean): Promise<Person> {
    return firstValueFrom(
      this.http.post<Person>(`${this.url(sheet)}/${id}/hold`, { held }, {
        headers: this.session.headers(),
      }),
    );
  }

  /** The sheet's patrons, in the order they were named. */
  patrons(sheet: string): Promise<Patron[]> {
    return firstValueFrom(
      this.http.get<Patron[]>(`${this.url(sheet)}/patrons`, { headers: this.session.headers() }),
    );
  }

  /** Name `patronId` as the person's patron; refused (409) for the person themselves or one already
   *  named. */
  addPatron(sheet: string, id: number, patronId: number): Promise<Patron> {
    return firstValueFrom(
      this.http.post<Patron>(`${this.url(sheet)}/${id}/patrons`, { patronId }, {
        headers: this.session.headers(),
      }),
    );
  }

  /** Add a DRAFT claim of `amount`, dated the sheet's today, for the person named `name`, adding
   *  them with grade A first when no one on the sheet has that name; all or nothing. */
  quickAdd(sheet: string, name: string, amount: string): Promise<QuickAdded> {
    return firstValueFrom(
      this.http.post<QuickAdded>(`/api/sheets/${encodeURIComponent(sheet)}/quick-add`, { name, amount }, {
        headers: this.session.headers(),
      }),
    );
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/people`;
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { Claim, cents, dueByOf } from './claims.service';
import { Grade } from './people.service';

export interface Rate {
  grade: Grade;
  /** The percent with two decimals, as text (e.g. "12.50"). */
  pct: string;
  /** The date the rate applies from (YYYY-MM-DD); null when it applies from the beginning of time. */
  from: string | null;
}

/** The grade's rate in force on a date: the one with the latest from-date on or before it, or the
 *  one with no from-date when none has; null when no rate applies yet. */
export function rateOn(rates: Rate[], grade: Grade, date: string): string | null {
  let best: Rate | null = null;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (best === null || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  return best?.pct ?? null;
}

/** What is due on an amount at a rate: amount times pct, divided by 100, rounded half to even to
 *  two decimals; null when there is no rate. Worked in whole cents and hundredths of a percent, so
 *  it is exact. */
export function dueCents(amountCents: number, pct: string | null): number | null {
  if (pct === null) return null;
  const product = BigInt(amountCents) * BigInt(Math.round(Number(pct) * 100));
  const negative = product < 0n;
  const abs = negative ? -product : product;
  let quotient = abs / 10000n;
  const remainder = abs % 10000n;
  if (remainder > 5000n || (remainder === 5000n && quotient % 2n === 1n)) quotient += 1n;
  return Number(negative ? -quotient : quotient);
}

/** What is due on a claim, in cents: a claim settled at a rate keeps what was due on it then; a
 *  claim a statement bound keeps the figure it was bound to (null when that was none); otherwise
 *  what is due on its amount at its person's grade's rate in force on the claim's date, raised to
 *  the sheet's floor (in cents) when below it, null when no rate applies then. */
export function claimDueCents(claim: Claim, rates: Rate[], grade: Grade, floorCents: number): number | null {
  if (claim.status === 'SETTLED' && claim.settledDue !== null) return cents(claim.settledDue);
  if (claim.stated) return claim.statedDue === null ? null : cents(claim.statedDue);
  const due = dueCents(cents(claim.amount), rateOn(rates, grade, claim.date));
  return due === null ? null : Math.max(due, floorCents);
}

/** What a late charge is worked from: the sheet's terms, in days, its today, and its late percent
 *  with two decimals. */
export interface Lateness {
  terms: number;
  today: string | null;
  latePct: string;
}

/** The late charge on a claim whose figure is figureCents, in cents: the late percent of that figure
 *  for every full 30 days the claim is overdue (OPEN, and past its due-by on the sheet's today),
 *  rounded like a due; 0 on any other claim. A statement never binds it; settling fixes it in. */
export function lateChargeCents(claim: Claim, figureCents: number, late: Lateness): number {
  if (claim.status !== 'OPEN' || late.today === null) return 0;
  const days = (Date.parse(late.today) - Date.parse(dueByOf(claim, late.terms))) / 86_400_000;
  const periods = Math.max(0, Math.floor(days / 30));
  return dueCents(figureCents * periods, late.latePct) ?? 0;
}

/** What is due on a claim as it shows and totals, in cents: its figure (see claimDueCents) plus its
 *  late charge; null when it has no figure. */
export function claimShownCents(
  claim: Claim,
  rates: Rate[],
  grade: Grade,
  floorCents: number,
  late: Lateness,
): number | null {
  const figure = claimDueCents(claim, rates, grade, floorCents);
  return figure === null ? null : figure + lateChargeCents(claim, figure, late);
}

// The rates of the grades on a sheet, read from and written to the server.
@Injectable({ providedIn: 'root' })
export class RatesService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheet: string): Promise<Rate[]> {
    return firstValueFrom(this.http.get<Rate[]>(this.url(sheet), { headers: this.session.headers() }));
  }

  /** A null from sets the rate that applies from the beginning of time. */
  set(sheet: string, grade: Grade, pct: string, from: string | null): Promise<Rate> {
    return firstValueFrom(
      this.http.put<Rate>(`${this.url(sheet)}/${grade}`, { pct, from }, { headers: this.session.headers() }),
    );
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/rates`;
  }
}
      margin: 0;
    }
    .claims {
      margin: 0.25rem 0 0;
      padding-left: 1rem;
    }
    .claims li span {
      margin-right: 0.75rem;
    }
  `,
})
export class Claims {
  private readonly session = inject(Session);
  private readonly service = inject(ClaimsService);

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  /** The person's claims, newest first. */
  readonly claims = input.required<Claim[]>();
  /** The person's grade. */
  readonly grade = input.required<Grade>();
  /** The sheet's rates. */
  readonly rates = input.required<Rate[]>();
  /** The sheet's floor, in cents: the least a claim's live due can be. */
  readonly floor = input.required<number>();
  /** The sheet's periods. */
  readonly periods = input.required<Period[]>();
  /** The sheet's terms, in days: how long after its date a claim is due by. */
  readonly terms = input.required<number>();
  /** The sheet's late percent, with two decimals. */
  readonly latePct = input.required<string>();
  /** A claim was added or saved. */
  readonly saved = output<Claim>();

  protected readonly amount = signal('');
  protected readonly date = signal('');
  protected readonly note = signal('');
  protected readonly editingId = signal<number | null>(null);
  protected readonly error = signal<string | null>(null);
  /** A submit is waiting for its answer; another submit meanwhile is ignored. */
  private submitting = false;
  /** The error of the last refused action on each claim, by claim id. */
  protected readonly rowErrors = signal<Record<number, string>>({});
  protected readonly actions: { action: ClaimAction; label: string }[] = [
    { action: 'open', label: 'Open' },
    { action: 'settle', label: 'Settle' },
    { action: 'void', label: 'Void' },
  ];

  protected fieldId(field: string): string {
    return `claim-${this.personId()}-${field}`;
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  /** What is due on the claim at the person's rate in force on the claim's date; n/a when no rate of
   *  their grade applies then; never below the sheet's floor; with its late charge added while it is
   *  overdue. A claim settled at a rate keeps what was due on it then; one settled without a rate
   *  fixed nothing. */
  protected dueOf(claim: Claim): string {
    const late = { terms: this.terms(), today: this.session.today(), latePct: this.latePct() };
    const due = claimShownCents(claim, this.rates(), this.grade(), this.floor(), late);
    return due === null ? 'n/a' : money(due);
  }

  protected dueBy(claim: Claim): string {
    return dueByOf(claim, this.terms());
  }

  protected isOverdue(claim: Claim): boolean {
    return overdue(claim, this.terms(), this.session.today());
  }

  /** The name of the period whose dates contain the claim's date; empty when none does. */
  protected periodOf(claim: Claim): string {
    return periodOn(this.periods(), claim.date)?.name ?? '';
  }

  /** Open the claim's editor; only a DRAFT can be edited, so the edit of any other claim is refused with
   *  an error on the claim (an open claim is changed by voiding it and adding a new one). */
  protected edit(claim: Claim): void {
    this.clearRowError(claim.id);
    if (claim.status !== 'DRAFT') {
      if (this.editingId() === claim.id) this.reset();
      this.rowErrors.update((errors) => ({
        ...errors,
        [claim.id]: 'Only a draft claim can be edited; void it and add a new one instead.',
      }));
      return;
    }
    this.editingId.set(claim.id);
    this.amount.set(claim.amount);
    this.date.set(claim.date);
    this.note.set(claim.note);
    this.error.set(null);
  }

  /** Change the claim's status; a change its status does not allow, a settle by the user who opened
   *  the claim, or a clerk's settle of a claim whose due is above the clerk limit, is refused with an error. */

